#![forbid(unsafe_code)]
#![doc = include_str!("../README.md")]

extern crate self as jsonllm;

use std::collections::BTreeMap;

pub use clairic_client::{Client, Field, Request, Response};
pub use jsonllm_derive::JsonGen;
pub use jsonllm_shared::{Error, JsonField, ListItem, clairic_client, decode_field, serde_json};

/// A type whose fields can be generated by Clairic.
///
/// Derive this trait with `#[derive(jsonllm::JsonGen)]`, then import the trait
/// to call its methods. The derive requires a nonempty named struct whose field
/// types implement [`JsonField`]. No serde derive is needed.
///
/// ```
/// use jsonllm::{JsonGen, clairic_client::FieldType};
///
/// #[derive(jsonllm::JsonGen)]
/// struct Product {
///     /// Product name as printed on the label.
///     name: String,
///     price: Option<f64>,
/// }
///
/// let fields = Product::fields();
/// assert_eq!(fields["name"].kind, FieldType::Text);
/// assert_eq!(fields["price"].kind, FieldType::Number);
/// ```
pub trait JsonGen: Sized {
    /// Build the request schema from the Rust fields.
    ///
    /// Field doc comments supply instructions. Field-level `jsonllm` attributes
    /// can override the wire name and instructions. Optional fields use the
    /// same schema as their inner type; they still require an answer entry.
    fn fields() -> BTreeMap<String, Field>;

    /// Decode a response without making a network request.
    ///
    /// The derived implementation ignores extra answers and decodes values
    /// without coercion. It does not retain usage or confidence metadata;
    /// keep the original [`Response`] when you need those details.
    ///
    /// # Errors
    ///
    /// The derived implementation returns [`Error::Truncated`] before decoding
    /// a truncated response, [`Error::MissingField`] for an absent answer, and
    /// [`Error::InvalidField`] for a value that the field type rejects.
    /// A present null value is valid for `Option<T>` and decodes to `None`.
    fn from_response(response: &Response) -> Result<Self, Error>;

    /// Generate from text with the client's configured timeout and endpoint.
    ///
    /// This sends one request using [`Self::fields`] and decodes the result
    /// with [`Self::from_response`]. Import this trait before calling the
    /// method. See the [crate example](crate) for client and runtime setup.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Upstream`] if request validation or transport fails,
    /// [`Error::Truncated`] if the response is truncated, or a decoding error
    /// from [`Self::from_response`]. Requests are not retried automatically.
    fn generate(
        client: &Client,
        state: impl Into<String>,
    ) -> impl Future<Output = Result<Self, Error>> {
        Self::generate_with(client, Request::new(state))
    }

    /// Generate with images or other request options.
    ///
    /// Type-derived fields replace all fields on the supplied request. The
    /// model, text, images, reference date, and response options are preserved.
    /// See the [image example](crate#images-and-response-handling).
    ///
    /// # Errors
    ///
    /// Returns the same request, truncation, and decoding errors as
    /// [`Self::generate`]. No automatic retry is performed.
    fn generate_with(
        client: &Client,
        mut request: Request,
    ) -> impl Future<Output = Result<Self, Error>> {
        request.fields = Self::fields();
        async move {
            tracing::debug!(
                fields = request.fields.len(),
                "starting typed Clairic generation"
            );
            let result = match client.run(&request).await {
                Ok(response) if response.truncated => Err(Error::Truncated),
                Ok(response) => Self::from_response(&response),
                Err(error) => Err(Error::Upstream(error)),
            };
            tracing::debug!(
                success = result.is_ok(),
                "completed typed Clairic generation"
            );
            result
        }
    }
}
